"use client"

import { useQuery } from "@tanstack/react-query"
import { StatCard } from "../stat-card"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Alert, AlertDescription } from "@/components/ui/alert"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { 
  CheckCircle2, 
  ArrowUpRight, 
  TrendingUp, 
  Calendar, 
  Building2,
  DollarSign,
  CreditCard,
  Layers,
  Activity,
  Wallet
} from "lucide-react"
import { 
  fetchGlobalIncomeStatement, 
  fetchGlobalBalanceSheet, 
  fetchCompanyComparison,
  fetchRecurringTransactions,
  fetchGlobalFinancialSummary
} from "@/lib/api"
import { useState } from "react"

interface DashboardOverviewProps {
  onNavigate: (tab: string) => void
}

export function DashboardOverview({ onNavigate }: DashboardOverviewProps) {
  const currentYear = new Date().getFullYear()
  const today = new Date().toISOString().split('T')[0]
  
  const [selectedYear, setSelectedYear] = useState(currentYear)

  // Fetch global financial data
  const { data: financialSummary, isLoading: financialSummaryLoading } = useQuery({
    queryKey: ["global-financial-summary", selectedYear],
    queryFn: () => fetchGlobalFinancialSummary(selectedYear),
  })
  
  const { data: incomeStatement, isLoading: incomeLoading } = useQuery({
    queryKey: ["global-income-statement", selectedYear],
    queryFn: () => fetchGlobalIncomeStatement(selectedYear),
  })

  const { data: balanceSheet, isLoading: balanceLoading } = useQuery({
    queryKey: ["global-balance-sheet", today],
    queryFn: () => fetchGlobalBalanceSheet(today),
  })

  const { data: companyComparison, isLoading: comparisonLoading } = useQuery({
    queryKey: ["company-comparison", selectedYear],
    queryFn: () => fetchCompanyComparison(selectedYear),
  })

  const { data: recurringTransactions, isLoading: recurringLoading } = useQuery({
    queryKey: ["recurring-transactions"],
    queryFn: fetchRecurringTransactions,
  })

  const isLoading = financialSummaryLoading || incomeLoading || balanceLoading || comparisonLoading || recurringLoading 

  if (isLoading) {
    return (
      <div className="text-center py-12 text-xs text-muted-foreground">
        Loading dashboard data...
      </div>
    )
  }

  // Calculate metrics from financial summary (primary source)
  const totalRevenue = financialSummary?.summary?.revenue?.total || incomeStatement?.summary?.totalRevenue || 0
  const totalExpenses = financialSummary?.summary?.expenses?.total || incomeStatement?.summary?.totalOperatingExpenses || 0
  const netIncome = financialSummary?.summary?.netProfit || incomeStatement?.summary?.totalNetProfit || 0
  const totalAssets = financialSummary?.summary?.assets || balanceSheet?.summary?.totalAssets || 0
  const totalLiabilities = financialSummary?.summary?.liabilities || balanceSheet?.summary?.totalLiabilities || 0
  
  // Additional metrics from financial summary
  const totalCompanies = financialSummary?.summary?.totalCompanies || 0
  const totalTransactions = financialSummary?.summary?.totalTransactions || 0
  const costOfSales = financialSummary?.summary?.costOfSales || 0
  const averageRevenuePerCompany = financialSummary?.summary?.revenue?.averagePerCompany || 0
  const averageExpensesPerCompany = financialSummary?.summary?.expenses?.averagePerCompany || 0
  const equity = totalAssets - totalLiabilities

  return (
    <div className="space-y-4">
      {/* Year Selector - Compact */}
      <div className="flex items-center justify-between gap-3">
        <Alert className="flex-1 bg-emerald-50 dark:bg-emerald-950/20 border-emerald-200 dark:border-emerald-800 py-2">
          <CheckCircle2 className="h-3.5 w-3.5 text-emerald-600" />
          <AlertDescription className="text-xs text-emerald-700 dark:text-emerald-400">
            <strong className="font-semibold">Global Overview</strong> — {selectedYear} • {totalCompanies} companies • {totalTransactions.toLocaleString()} transactions
          </AlertDescription>
        </Alert>
        
        <div className="flex items-center gap-1.5">
          <Calendar className="h-3.5 w-3.5 text-muted-foreground" />
          <select
            value={selectedYear}
            onChange={(e) => setSelectedYear(Number(e.target.value))}
            className="border rounded px-2 py-1 text-xs bg-background focus:outline-none focus:ring-1 focus:ring-primary"
          >
            {[currentYear - 2, currentYear - 1, currentYear, currentYear + 1].map(year => (
              <option key={year} value={year}>{year}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Income Statement Section - Related Metrics Grouped */}
      <div className="space-y-3">
        <div className="flex items-center gap-2">
          <TrendingUp className="h-4 w-4 text-muted-foreground" />
          <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Income Statement</h3>
        </div>
        
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-3">
          <StatCard
            label="Total Revenue"
            value={`RWF ${totalRevenue.toLocaleString()}`}
            change={`Avg: ${averageRevenuePerCompany.toLocaleString()}/co`}
            changeType="neutral"
            variant="revenue"
          />
          <Card className="shadow-sm border-border/40">
            <CardContent className="pt-4 pb-3">
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <p className="text-[10px] text-muted-foreground font-medium mb-1">Cost of Sales</p>
                  <p className="text-lg font-serif font-bold">RWF {costOfSales.toLocaleString()}</p>
                  <p className="text-[10px] text-muted-foreground mt-0.5">
                    {totalRevenue > 0 ? `${((costOfSales/totalRevenue)*100).toFixed(1)}% of revenue` : '—'}
                  </p>
                </div>
                <div className="h-8 w-8 rounded-full bg-orange-100 dark:bg-orange-950/30 flex items-center justify-center flex-shrink-0">
                  <DollarSign className="h-4 w-4 text-orange-600" />
                </div>
              </div>
            </CardContent>
          </Card>
          <StatCard
            label="Total Expenses"
            value={`RWF ${totalExpenses.toLocaleString()}`}
            change={`Avg: ${averageExpensesPerCompany.toLocaleString()}/co`}
            changeType="neutral"
            variant="expense"
          />
          <StatCard
            label="Net Income"
            value={`RWF ${netIncome.toLocaleString()}`}
            change={netIncome >= 0 ? "Profit" : "Loss"}
            changeType={netIncome >= 0 ? "positive" : "negative"}
            variant="profit"
          />
          <Card className="shadow-sm border-border/40">
            <CardContent className="pt-4 pb-3">
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <p className="text-[10px] text-muted-foreground font-medium mb-1">Profit Margin</p>
                  <p className="text-lg font-serif font-bold">
                    {totalRevenue > 0 ? `${((netIncome/totalRevenue)*100).toFixed(1)}%` : '—'}
                  </p>
                  <p className="text-[10px] text-muted-foreground mt-0.5">Net margin</p>
                </div>
                <div className="h-8 w-8 rounded-full bg-purple-100 dark:bg-purple-950/30 flex items-center justify-center flex-shrink-0">
                  <Activity className="h-4 w-4 text-purple-600" />
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>

      {/* Balance Sheet Section - Related Metrics Grouped */}
      <div className="space-y-3">
        <div className="flex items-center gap-2">
          <Wallet className="h-4 w-4 text-muted-foreground" />
          <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Balance Sheet</h3>
          <span className="text-[10px] text-muted-foreground">as of {new Date(today).toLocaleDateString()}</span>
        </div>
        
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
          <StatCard
            label="Total Assets"
            value={`RWF ${totalAssets.toLocaleString()}`}
            change="Resources owned"
            changeType="neutral"
            variant="cash"
          />
          <Card className="shadow-sm border-border/40">
            <CardContent className="pt-4 pb-3">
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <p className="text-[10px] text-muted-foreground font-medium mb-1">Total Liabilities</p>
                  <p className="text-lg font-serif font-bold">RWF {totalLiabilities.toLocaleString()}</p>
                  <p className="text-[10px] text-muted-foreground mt-0.5">
                    {totalAssets > 0 ? `${((totalLiabilities/totalAssets)*100).toFixed(1)}% of assets` : '—'}
                  </p>
                </div>
                <div className="h-8 w-8 rounded-full bg-red-100 dark:bg-red-950/30 flex items-center justify-center flex-shrink-0">
                  <CreditCard className="h-4 w-4 text-red-600" />
                </div>
              </div>
            </CardContent>
          </Card>
          <Card className="shadow-sm border-border/40">
            <CardContent className="pt-4 pb-3">
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <p className="text-[10px] text-muted-foreground font-medium mb-1">Total Equity</p>
                  <p className="text-lg font-serif font-bold">RWF {equity.toLocaleString()}</p>
                  <p className="text-[10px] text-muted-foreground mt-0.5">Assets - Liabilities</p>
                </div>
                <div className="h-8 w-8 rounded-full bg-blue-100 dark:bg-blue-950/30 flex items-center justify-center flex-shrink-0">
                  <Building2 className="h-4 w-4 text-blue-600" />
                </div>
              </div>
            </CardContent>
          </Card>
          <Card className="shadow-sm border-border/40">
            <CardContent className="pt-4 pb-3">
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <p className="text-[10px] text-muted-foreground font-medium mb-1">Debt-to-Equity</p>
                  <p className="text-lg font-serif font-bold">
                    {equity > 0 ? (totalLiabilities/equity).toFixed(2) : '—'}
                  </p>
                  <p className="text-[10px] text-muted-foreground mt-0.5">Leverage ratio</p>
                </div>
                <div className="h-8 w-8 rounded-full bg-violet-100 dark:bg-violet-950/30 flex items-center justify-center flex-shrink-0">
                  <Activity className="h-4 w-4 text-violet-600" />
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>

      {/* Payment Methods Breakdown - Compact Cards */}
      {financialSummary?.summary?.paymentMethods && financialSummary.summary.paymentMethods.length > 0 && (
        <Card className="shadow-sm border-border/40">
          <CardHeader className="flex flex-row items-center justify-between pb-3 pt-4">
            <div>
              <CardTitle className="text-xs font-semibold">Payment Methods Distribution</CardTitle>
              <p className="text-[10px] text-muted-foreground mt-0.5">
                Transaction breakdown by payment type
              </p>
            </div>
            <CreditCard className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent className="pb-4">
            <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-3">
              {financialSummary.summary.paymentMethods.map((method: any, index: number) => {
                const totalPaymentAmount = financialSummary.summary.paymentMethods.reduce(
                  (sum: number, m: any) => sum + m.totalAmount, 
                  0
                )
                const totalPaymentCount = financialSummary.summary.paymentMethods.reduce(
                  (sum: number, m: any) => sum + m.count, 
                  0
                )
                const amountPercentage = totalPaymentAmount > 0 
                  ? ((method.totalAmount / totalPaymentAmount) * 100).toFixed(1) 
                  : "0.0"
                const countPercentage = totalPaymentCount > 0 
                  ? ((method.count / totalPaymentCount) * 100).toFixed(1) 
                  : "0.0"

                const bgColors = [
                  "bg-blue-50 dark:bg-blue-950/20 border-blue-200 dark:border-blue-800",
                  "bg-purple-50 dark:bg-purple-950/20 border-purple-200 dark:border-purple-800",
                  "bg-green-50 dark:bg-green-950/20 border-green-200 dark:border-green-800",
                  "bg-amber-50 dark:bg-amber-950/20 border-amber-200 dark:border-amber-800",
                ]

                return (
                  <Card key={method.method} className={`${bgColors[index % 4]} border shadow-none`}>
                    <CardContent className="pt-3 pb-3">
                      <div className="space-y-1.5">
                        <div className="flex items-center justify-between">
                          <span className="text-[10px] font-semibold uppercase text-muted-foreground">
                            {method.method.replace('_', ' ')}
                          </span>
                          <Badge variant="outline" className="text-[9px] h-4 px-1">{method.count}</Badge>
                        </div>
                        <p className="text-base font-serif font-bold">
                          RWF {method.totalAmount.toLocaleString()}
                        </p>
                        <div className="flex items-center gap-2 text-[10px] text-muted-foreground">
                          <span>{amountPercentage}% amt</span>
                          <span>•</span>
                          <span>{countPercentage}% txns</span>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                )
              })}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Category Breakdown - Compact Table */}
      {financialSummary?.summary?.categoryBreakdown && financialSummary.summary.categoryBreakdown.length > 0 && (
        <Card className="shadow-sm border-border/40">
          <CardHeader className="flex flex-row items-center justify-between pb-3 pt-4">
            <div>
              <CardTitle className="text-xs font-semibold">Category Breakdown</CardTitle>
              <p className="text-[10px] text-muted-foreground mt-0.5">
                {financialSummary.summary.categoryBreakdown.length} categories
              </p>
            </div>
            <Layers className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent className="pb-4">
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow className="border-b">
                    <TableHead className="text-[10px] h-8">Category</TableHead>
                    <TableHead className="text-[10px] h-8">Path</TableHead>
                    <TableHead className="text-right text-[10px] h-8">Transactions</TableHead>
                    <TableHead className="text-right text-[10px] h-8">Total Amount</TableHead>
                    <TableHead className="text-right text-[10px] h-8">% Share</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {financialSummary.summary.categoryBreakdown.map((category: any) => {
                    const totalCategoryAmount = financialSummary.summary.categoryBreakdown.reduce(
                      (sum: number, cat: any) => sum + cat.totalAmount, 
                      0
                    )
                    const percentage = totalCategoryAmount > 0 
                      ? ((category.totalAmount / totalCategoryAmount) * 100).toFixed(1) 
                      : "0.0"

                    return (
                      <TableRow key={category.categoryId} className="hover:bg-muted/50 border-b">
                        <TableCell className="font-medium text-xs py-2">
                          {category.categoryName}
                        </TableCell>
                        <TableCell className="text-[10px] text-muted-foreground py-2">
                          {category.categoryPath}
                        </TableCell>
                        <TableCell className="text-right py-2">
                          <Badge variant="secondary" className="text-[9px] h-4 px-1.5">
                            {category.transactionCount}
                          </Badge>
                        </TableCell>
                        <TableCell className="text-right font-serif text-xs font-semibold text-emerald-600 dark:text-emerald-400 py-2">
                          RWF {category.totalAmount.toLocaleString()}
                        </TableCell>
                        <TableCell className="text-right py-2">
                          <div className="flex items-center justify-end gap-1.5">
                            <div className="h-1.5 w-12 bg-muted rounded-full overflow-hidden">
                              <div 
                                className="h-full bg-emerald-500" 
                                style={{ width: `${percentage}%` }}
                              />
                            </div>
                            <span className="text-[10px] font-medium w-8">{percentage}%</span>
                          </div>
                        </TableCell>
                      </TableRow>
                    )
                  })}
                </TableBody>
              </Table>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Company Comparison - Compact with Top Performers */}
      <Card className="shadow-sm border-border/40">
        <CardHeader className="flex flex-row items-center justify-between pb-3 pt-4">
          <div>
            <CardTitle className="text-xs font-semibold">Company Performance</CardTitle>
            <p className="text-[10px] text-muted-foreground mt-0.5">
              {companyComparison?.summary?.totalCompanies || 0} companies • Year {selectedYear}
            </p>
          </div>
          <Button variant="outline" size="sm" className="h-7 text-xs" onClick={() => onNavigate("companies")}>
            Details
            <ArrowUpRight className="h-3 w-3 ml-1" />
          </Button>
        </CardHeader>
        <CardContent className="pb-4">
          {/* Top Performers - Inline Summary */}
          {companyComparison?.summary?.topPerformers && (
            <div className="mb-4 grid grid-cols-1 md:grid-cols-3 gap-2">
              <div className="p-2.5 bg-emerald-50 dark:bg-emerald-950/20 rounded border border-emerald-200 dark:border-emerald-800">
                <p className="text-[9px] font-semibold text-emerald-700 dark:text-emerald-400 uppercase tracking-wide mb-1">
                  Top Revenue
                </p>
                {companyComparison.summary.topPerformers.byRevenue.slice(0, 1).map((company: any) => (
                  <div key={company.companyId}>
                    <p className="font-medium text-xs">{company.companyName}</p>
                    <p className="text-xs font-serif font-bold text-emerald-600">
                      RWF {company.revenue.toLocaleString()}
                    </p>
                  </div>
                ))}
              </div>

              <div className="p-2.5 bg-blue-50 dark:bg-blue-950/20 rounded border border-blue-200 dark:border-blue-800">
                <p className="text-[9px] font-semibold text-blue-700 dark:text-blue-400 uppercase tracking-wide mb-1">
                  Top Profit
                </p>
                {companyComparison.summary.topPerformers.byProfit.slice(0, 1).map((company: any) => (
                  <div key={company.companyId}>
                    <p className="font-medium text-xs">{company.companyName}</p>
                    <p className="text-xs font-serif font-bold text-blue-600">
                      RWF {company.netProfit.toLocaleString()}
                    </p>
                  </div>
                ))}
              </div>

              <div className="p-2.5 bg-violet-50 dark:bg-violet-950/20 rounded border border-violet-200 dark:border-violet-800">
                <p className="text-[9px] font-semibold text-violet-700 dark:text-violet-400 uppercase tracking-wide mb-1">
                  Best Margin
                </p>
                {companyComparison.summary.topPerformers.byProfitMargin.slice(0, 1).map((company: any) => (
                  <div key={company.companyId}>
                    <p className="font-medium text-xs">{company.companyName}</p>
                    <p className="text-xs font-serif font-bold text-violet-600">
                      {company.profitMargin}%
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Company Table - Compact */}
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow className="border-b">
                  <TableHead className="text-[10px] h-8">Company</TableHead>
                  <TableHead className="text-right text-[10px] h-8">Revenue</TableHead>
                  <TableHead className="text-right text-[10px] h-8">Expenses</TableHead>
                  <TableHead className="text-right text-[10px] h-8">Net Profit</TableHead>
                  <TableHead className="text-right text-[10px] h-8">Margin</TableHead>
                  <TableHead className="text-right text-[10px] h-8">Assets</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {companyComparison?.summary?.allCompanies?.map((company: any) => {
                  const margin = company.profitMargin || "0"
                  
                  return (
                    <TableRow key={company.companyId} className="hover:bg-muted/50 border-b">
                      <TableCell className="font-medium text-xs py-2">
                        <div className="flex items-center gap-1.5">
                          <Building2 className="h-3 w-3 text-muted-foreground" />
                          {company.companyName}
                        </div>
                      </TableCell>
                      <TableCell className="text-right font-serif text-xs text-emerald-600 dark:text-emerald-400 py-2">
                        {company.revenue.toLocaleString()}
                      </TableCell>
                      <TableCell className="text-right font-serif text-xs text-red-600 dark:text-red-400 py-2">
                        {company.expenses.toLocaleString()}
                      </TableCell>
                      <TableCell className={`text-right font-serif text-xs font-semibold py-2 ${
                        company.netProfit >= 0 
                          ? "text-emerald-600 dark:text-emerald-400" 
                          : "text-red-600 dark:text-red-400"
                      }`}>
                        {company.netProfit.toLocaleString()}
                      </TableCell>
                      <TableCell className="text-right py-2">
                        <Badge variant={Number(margin) >= 0 ? "default" : "destructive"} className="text-[9px] h-4 px-1.5">
                          {margin}%
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right font-serif text-xs py-2">
                        {company.assets.toLocaleString()}
                      </TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>

      {/* Recurring Transactions - Compact */}
      <Card className="shadow-sm border-border/40">
        <CardHeader className="flex flex-row items-center justify-between pb-3 pt-4">
          <div>
            <CardTitle className="text-xs font-semibold">Recurring Transactions</CardTitle>
            <p className="text-[10px] text-muted-foreground mt-0.5">
              {recurringTransactions?.transactions?.length || 0} active schedules
            </p>
          </div>
          <Button variant="outline" size="sm" className="h-7 text-xs" onClick={() => onNavigate("recurring")}>
            Manage
            <ArrowUpRight className="h-3 w-3 ml-1" />
          </Button>
        </CardHeader>
        <CardContent className="pb-4">
          {recurringTransactions?.transactions && recurringTransactions.transactions.length > 0 ? (
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow className="border-b">
                    <TableHead className="text-[10px] h-8">Company</TableHead>
                    <TableHead className="text-[10px] h-8">Description</TableHead>
                    <TableHead className="text-[10px] h-8">Frequency</TableHead>
                    <TableHead className="text-[10px] h-8">Category</TableHead>
                    <TableHead className="text-right text-[10px] h-8">Amount</TableHead>
                    <TableHead className="text-[10px] h-8">Status</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {recurringTransactions.transactions.slice(0, 5).map((transaction: any) => (
                    <TableRow key={transaction.id} className="hover:bg-muted/50 border-b">
                      <TableCell className="font-medium text-xs py-2">
                        <div className="flex items-center gap-1.5">
                          <Building2 className="h-3 w-3 text-muted-foreground" />
                          {transaction.company?.name || 'N/A'}
                        </div>
                      </TableCell>
                      <TableCell className="text-xs py-2">{transaction.description}</TableCell>
                      <TableCell className="py-2">
                        <Badge variant="outline" className="capitalize text-[9px] h-4 px-1.5">
                          {transaction.recurringFrequency}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-[10px] text-muted-foreground py-2">
                        {transaction.categoryPath || transaction.category?.name || 'N/A'}
                      </TableCell>
                      <TableCell className={`font-serif text-xs text-right py-2 ${
                        transaction.transactionType === 'debit' 
                          ? 'text-emerald-600 dark:text-emerald-400' 
                          : 'text-red-600 dark:text-red-400'
                      }`}>
                        {transaction.transactionType === 'credit' ? '-' : '+'}
                        {parseFloat(transaction.amount).toLocaleString()}
                      </TableCell>
                      <TableCell className="py-2">
                        <Badge variant={transaction.status === 'completed' ? "default" : "secondary"} className="text-[9px] h-4 px-1.5">
                          {transaction.status}
                        </Badge>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          ) : (
            <div className="text-center py-6 text-[10px] text-muted-foreground">
              No recurring transactions set up yet.
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  )
}